Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsremessaprodutoWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsremessaprodutoWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsremessaprodutoWWGridState")) Endif
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFREMPRODCODIGO" &TFremProdCodigo.FromString(&GridStateFilterValue.Value) &TFremProdCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMPRODDESCRICAO" &TFremProdDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODDESCRICAO_SEL" &TFremProdDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODUNPESO" &TFremProdUnPeso.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODUNPESO_SEL" &TFremProdUnPeso_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSCODIGO" &TFremProdAreEnsCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSCODIGO_SEL" &TFremProdAreEnsCodigo_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSSEQUENCIAL" &TFremProdAreEnsSequencial.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSSEQUENCIAL_SEL" &TFremProdAreEnsSequencial_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSTURNO_SEL" &TFremProdAreEnsTurno_SelsJson = &GridStateFilterValue.Value &TFremProdAreEnsTurno_Sels.FromJson(&TFremProdAreEnsTurno_SelsJson) Case &GridStateFilterValue.Name = !"TFREMPRODQTDE" &TFremProdQtde.FromString(&GridStateFilterValue.Value) &TFremProdQtde_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMPRODPERCAPTA" &TFremProdPerCapta.FromString(&GridStateFilterValue.Value) &TFremProdPerCapta_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"PARM_&PREFCODIGO" &prefCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"PARM_&REMCODIGO" &remCodigo.FromString(&GridStateFilterValue.Value) EndCase EndFor If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'REMPRODDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &remProdDescricao1.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'REMPRODDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &remProdDescricao2.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'REMPRODDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &remProdDescricao3.FromString(&GridStateDynamicFilter.Value) EndCase EndIf EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadremProdDescricaoOptions'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
